int main() {
    int N;
    scanf("%d", &N);

    int *A = (int*)malloc(N * sizeof(int));
    long long total = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        total += A[i];
    }

    // Duplicate for circular handling
    int size = 2 * N;
    long long *arr = (long long*)malloc(size * sizeof(long long));
    for (int i = 0; i < N; i++) {
        arr[i] = A[i];
        arr[i + N] = A[i];
    }

    // Prefix sums for fast range sum
    long long *prefix = (long long*)malloc((size + 1) * sizeof(long long));
    prefix[0] = 0;
    for (int i = 0; i < size; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }

    long long ans = 0;
    int j = 0, k = 0;

    for (int i = 0; i < N; i++) {
        // Ensure j is at least i+1 and the first piece <= total/3
        if (j < i + 1) j = i + 1;
        while (j < i + N && prefix[j] - prefix[i] <= total / 3) {
            j++;
        }
        j--; // last index where first piece <= total/3

        if (j < i + 1) continue;

        // Now find k for second piece
        if (k < j + 1) k = j + 1;
        while (k < i + N && prefix[k] - prefix[j] <= prefix[j] - prefix[i]) {
            k++;
        }
        k--; // best k where second piece <= first piece

        if (k < j + 1 || k >= i + N) continue;

        long long piece1 = prefix[j] - prefix[i];
        long long piece2 = prefix[k] - prefix[j];
        long long piece3 = total - piece1 - piece2;

        long long min_piece = piece1;
        if (piece2 < min_piece) min_piece = piece2;
        if (piece3 < min_piece) min_piece = piece3;

        if (min_piece > ans) ans = min_piece;
    }

    printf("%lld\n", ans);

    free(A);
    free(arr);
    free(prefix);
    return 0;
}

