typedef long long ll;

static ll min3(ll a, ll b, ll c) {
    ll m = a;
    if (b < m) m = b;
    if (c < m) m = c;
    return m;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    ll total = 0;
    for (int i = 0; i < N; i++) {
        scanf("%lld", &A[i]);
        total += A[i];
    }

    /* Duplicate array to handle circular structure */
    ll *B = (ll *)malloc(sizeof(ll) * (2 * N));
    for (int i = 0; i < 2 * N; i++) B[i] = A[i % N];

    /* Prefix sums on duplicated array */
    ll *pref = (ll *)malloc(sizeof(ll) * (2 * N + 1));
    pref[0] = 0;
    for (int i = 0; i < 2 * N; i++) pref[i + 1] = pref[i] + B[i];

    ll ans = 0;

    /* Fix first cut at notch s, second cut at i, third cut at j */
    for (int s = 0; s < N; s++) {
        int j = s + 1;
        for (int i = s + 1; i <= s + N - 2; i++) {
            if (j < i + 1) j = i + 1;

            /* Move j while it improves balance between second and third piece */
            while (j < s + N - 1) {
                ll x1 = pref[i] - pref[s];       /* piece 1 */
                ll y1 = pref[j] - pref[i];       /* piece 2 */
                ll z1 = total - x1 - y1;         /* piece 3 */

                ll y2 = pref[j + 1] - pref[i];
                ll z2 = total - x1 - y2;

                ll cur = min3(x1, y1, z1);
                ll nxt = min3(x1, y2, z2);

                if (nxt >= cur) j++;
                else break;
            }

            /* Check current j */
            {
                ll x = pref[i] - pref[s];
                ll y = pref[j] - pref[i];
                ll z = total - x - y;
                ll val = min3(x, y, z);
                if (val > ans) ans = val;
            }

            /* Also check j+1 if valid, since optimum is around boundary */
            if (j < s + N - 1) {
                ll x = pref[i] - pref[s];
                ll y = pref[j + 1] - pref[i];
                ll z = total - x - y;
                ll val = min3(x, y, z);
                if (val > ans) ans = val;
            }
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(B);
    free(pref);
    return 0;
}

