int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        total += a[i];
    }

    // Expand array to handle circular cuts easily
    vector<long long> arr(2 * n);
    for (int i = 0; i < n; i++) {
        arr[i] = a[i];
        arr[i + n] = a[i];
    }

    // Prefix sums
    vector<long long> pref(2 * n + 1, 0);
    for (int i = 0; i < 2 * n; i++) {
        pref[i + 1] = pref[i] + arr[i];
    }

    long long low = 0, high = total / 3, ans = 0;

    while (low <= high) {
        long long mid = (low + high) / 2;
        bool possible = false;

        // try each possible first cut position
        for (int i = 0; i < n; i++) {
            // find first cut end that gives >= mid
            int j = lower_bound(pref.begin(), pref.end(), pref[i] + mid) - pref.begin();
            if (j > i + n) continue; // not possible from here
            long long piece1 = pref[j] - pref[i];
            if (piece1 < mid) continue;

            // find second cut end that gives >= mid
            int k = lower_bound(pref.begin(), pref.end(), pref[j] + mid) - pref.begin();
            if (k > i + n) continue;
            long long piece2 = pref[k] - pref[j];
            if (piece2 < mid) continue;

            long long piece3 = pref[i + n] - pref[k];
            if (piece3 >= mid) {
                possible = true;
                break;
            }
        }

        if (possible) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    cout << ans << "\n";
    return 0;
}

