int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long total = 0;
    for (auto x : a) total += x;

    // prefix sums on doubled array
    vector<long long> pre(2*n+1, 0);
    for (int i = 0; i < 2*n; i++) pre[i+1] = pre[i] + a[i%n];

    // Binary search on answer
    long long lo = 0, hi = total / 3;

    auto check = [&](long long mid) -> bool {
        // For each starting position, try to make 3 pieces each >= mid
        for (int i = 0; i < n; i++) {
            // find first cut j >= i such that sum(i..j) >= mid
            // sum(i..j) = pre[j+1] - pre[i]
            // pre[j+1] >= pre[i] + mid
            long long need1 = pre[i] + mid;
            int j = (int)(lower_bound(pre.begin(), pre.end(), need1) - pre.begin());
            // j is index in pre, so segment ends at notch j-1 (0-indexed in doubled)
            if (j > 2*n) continue;
            // second cut
            long long need2 = pre[j] + mid; // actually pre[j] is sum up to j
            // Wait, first piece is from i to j-1 (notch j-1 is cut point)
            // second piece starts at j-1
            int k = (int)(lower_bound(pre.begin(), pre.end(), pre[j] + mid) - pre.begin());
            if (k > 2*n) continue;
            // third piece: from k to i+n
            long long third = pre[i+n] - pre[k];
            if (third >= mid) return true;
        }
        return false;
    };

    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        if (check(mid)) lo = mid;
        else hi = mid - 1;
    }

    cout << lo << endl;
    return 0;
}

