    }

    // Duplicate the array to handle the circle as a line.
    vector<long long> B(2 * N);
    for (int i = 0; i < 2 * N; ++i) B[i] = A[i % N];

    // Prefix sums on duplicated array.
    vector<long long> pref(2 * N + 1, 0);
    for (int i = 0; i < 2 * N; ++i) pref[i + 1] = pref[i] + B[i];

    auto can = [&](long long x) -> bool {
        // For each start notch i, try to find two cuts so that
        // each of the three pieces has size at least x.
        int r1 = 0, r2 = 0;
        for (int i = 0; i < N; ++i) {
            if (r1 < i) r1 = i;
            while (r1 < i + N && pref[r1] - pref[i] < x) ++r1;
            if (r1 > i + N) continue;
            if (r2 < r1) r2 = r1;
            while (r2 < i + N && pref[r2] - pref[r1] < x) ++r2;
            if (r2 > i + N) continue;

            long long third = total - (pref[r2] - pref[i]);
            if (third >= x && r1 <= i + N && r2 <= i + N) return true;
        }
        return false;
    };

    long long low = 0, high = total / 3 + 1; // [low, high)
    while (high - low > 1) {
        long long mid = (low + high) / 2;
        if (can(mid)) low = mid;
        else high = mid;
    }

    cout << low << '\n';
    return 0;
}

import java.util.Scanner;

public class Baumkuchen {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N];
        long total = 0;
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
            total += A[i];
        }

        // Prefix sums on doubled array for circular handling
        long[] prefix = new long[2 * N + 1];
        for (int i = 1; i <= 2 * N; i++) {
            prefix[i] = prefix[i - 1] + A[(i - 1) % N];
        }

        long best = 0;
        int j = 1, k = 2;
        for (int i = 0; i < N; i++) {
            // Ensure j > i
            if (j <= i) j = i + 1;
            if (k <= j) k = j + 1;

            long target = total / 3;
            // Move j so that piece1 is as close to target as possible
            while (j < i + N && prefix[j] - prefix[i] < target) {
                j++;
            }
            // Move k so that piece2 is as close to target as possible
            while (k < j + N && prefix[k] - prefix[j] < target) {
                k++;
            }

            // Check the three candidates around j and k
            for (int dj = -1; dj <= 1; dj++) {
                for (int dk = -1; dk <= 1; dk++) {
                    int jj = j + dj;
                    int kk = k + dk;
                    if (jj > i && kk > jj && jj < i + N && kk < i + N) {
                        long piece1 = prefix[jj] - prefix[i];
                        long piece2 = prefix[kk] - prefix[jj];
                        long piece3 = total - piece1 - piece2;
                        long minPiece = Math.min(piece1, Math.min(piece2, piece3));
                        best = Math.max(best, minPiece);
                    }
                }
            }
        }

        System.out.println(best);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        long[] a = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + a[i];
        long S = pre[n];

        long lo = 0, hi = S / 3, ans = 0;
        while (lo <= hi) {
            long mid = (lo + hi) / 2;
            boolean ok = false;
            for (int i = 0; i <= n && !ok; i++) {
                int j = lowerBound(pre, pre[i] + mid, i+1, n+1);
                if (j > n) break;
                int k = lowerBound(pre, pre[j] + mid, j+1, n+1);
                if (k > n) break;
                if (S - pre[k] + pre[i] >= mid) ok = true;
            }
            if (ok) { ans = mid; lo = mid + 1; } else hi = mid - 1;
        }
        System.out.println(ans);
    }
    static int lowerBound(long[] arr, long val, int lo, int hi) {
        while (lo < hi) { int mid = (lo+hi)/2; if (arr[mid] < val) lo = mid+1; else hi = mid; }
        return lo;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long[] A = new long[N];
        long total = 0;
        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            total += A[i];
        }

        // Duplicate array to handle circular intervals.
        long[] B = new long[2 * N];
        for (int i = 0; i < 2 * N; i++) B[i] = A[i % N];

        // Prefix sums on duplicated array.
        long[] pref = new long[2 * N + 1];
        for (int i = 0; i < 2 * N; i++) pref[i + 1] = pref[i] + B[i];

        long low = 0, high = total / 3 + 1; // binary search on answer
        while (high - low > 1) {
            long mid = (low + high) >>> 1;
            if (can(mid, N, total, pref)) low = mid;
            else high = mid;
        }

        System.out.println(low);
    }

    static boolean can(long x, int N, long total, long[] pref) {
        int j = 0, k = 0;

        for (int i = 0; i < N; i++) {
            if (j < i) j = i;
            while (j < i + N && pref[j + 1] - pref[i] < x) j++;
            if (j >= i + N) continue;

            int firstEnd = j + 1; // first piece is [i, firstEnd)

            if (k < firstEnd) k = firstEnd;
            while (k < i + N && pref[k + 1] - pref[firstEnd] < x) k++;
            if (k >= i + N) continue;

            int secondEnd = k + 1; // second piece is [firstEnd, secondEnd)
            long third = total - (pref[secondEnd] - pref[i]);
            if (third >= x) return true;
        }
        return false;
    }
}

import sys

def solve() -> None:
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    a = list(map(int, input_data[1:1+n]))

    # Double the array to handle circular cuts
    doubled = a + a
    prefix = [0] * (2 * n + 1)
    for i in range(2 * n):
        prefix[i+1] = prefix[i] + doubled[i]

    def can(x: int) -> bool:
        # Check if we can cut so that each piece >= x
        # For each possible first cut position i (0..n-1)
        for i in range(n):
            # Find first cut end: smallest j where sum[i:j] >= x
            lo, hi = i+1, i+n+1
            while lo < hi:
                mid = (lo + hi) // 2
                if prefix[mid] - prefix[i] >= x:
                    hi = mid
                else:
                    lo = mid + 1
            if lo == i+n+1:
                continue
            j = lo
            # Find second cut end: smallest k where sum[j:k] >= x
            lo, hi = j+1, i+n+1
            while lo < hi:
                mid = (lo + hi) // 2
                if prefix[mid] - prefix[j] >= x:
                    hi = mid
                else:
                    lo = mid + 1
            if lo == i+n+1:
                continue
            k = lo
            # Check remaining piece
            if prefix[i+n] - prefix[k] >= x:
                return True
        return False

    lo, hi = 0, sum(a) // 3
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if can(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1

    print(ans)

if __name__ == "__main__":
    solve()
